node.doctext:
Here two or three workarounds (can't test the latter)<P>

<c>    
use utf8;
use strict;
use warnings;

use Data::Dumper;

my %h = (a => 'alfa', b => 'beta'); 



print "\n\nWorkaround 1 \n";
print map { "\t>>$_<<\n" } "$h{a}", "$h{111}", "$h{b}"; 
print "after third:\n", Dumper(\%h); 



print "\n\nWorkaround 2 \n";
print map { "\t>>$h{$_}<<\n" } qw/a 222 b/; 
print "after third:\n", Dumper(\%h); 



# print "\n\nWorkaround 3 \n";
# no autovivification;
# print map { "\t>>$_<<\n" } $h{a}, $h{333}, $h{b}; 
# print "after third:\n", Dumper(\%h); 


</c><P>


